// orders.bynk
context orders

exports transparent { Paid }

event Paid = { id: String }

// mailer.bynk
context mailer

consumes orders
consumes bynk { Events }

event Sent = { id: String }

Events.emit[Paid](Paid { id: "x" })   // ✗ `Paid` belongs to `orders`
Events.emit[Sent](Sent { id: "x" })   // ✓ `Sent` is declared here
